38	      const content = readFileSync(f.path, 'utf-8');
39	      const match = content.match(f.regex);
40	      if (match) return parseInt(match[1]);
41	    }
42	  }
43	  if (existsSync('package.json')) {
44	    const pkg = JSON.parse(readFileSync('package.json', 'utf-8'));
